export const AUTOMERGE_LABEL = "clawsweeper:automerge";
export const AUTOFIX_LABEL = "clawsweeper:autofix";
export const HUMAN_REVIEW_LABEL = "clawsweeper:human-review";
export const MANUAL_ONLY_LABEL = "clawsweeper:manual-only";

export const CLOSE_PROTECTED_LABEL_NAMES = [
  "security",
  "beta-blocker",
  "release-blocker",
  "maintainer",
] as const;

export const AUTOMERGE_BLOCKING_LABEL_NAMES = [
  ...CLOSE_PROTECTED_LABEL_NAMES,
  AUTOFIX_LABEL,
  HUMAN_REVIEW_LABEL,
  MANUAL_ONLY_LABEL,
  "clawsweeper:autogenerated",
  "clawsweeper:merge-ready",
  "clawsweeper:needs-security-review",
  "clawsweeper:needs-maintainer-review",
  "clawsweeper:needs-product-decision",
] as const;

export const PR_AUTO_CLOSE_EXEMPT_LABEL_NAMES = [
  HUMAN_REVIEW_LABEL,
  MANUAL_ONLY_LABEL,
  AUTOMERGE_LABEL,
  AUTOFIX_LABEL,
] as const;

export const EXACT_REVIEW_CLOSE_GUARD_LABELS = [
  ...CLOSE_PROTECTED_LABEL_NAMES,
  ...PR_AUTO_CLOSE_EXEMPT_LABEL_NAMES,
] as const;

const EXACT_REVIEW_CLOSE_GUARD_LABEL_SET = new Set<string>(EXACT_REVIEW_CLOSE_GUARD_LABELS);

export function isExactReviewCloseGuardLabel(value: unknown): boolean {
  return EXACT_REVIEW_CLOSE_GUARD_LABEL_SET.has(
    String(value ?? "")
      .trim()
      .toLowerCase(),
  );
}

const REVIEW_SOURCE_LABEL_EXCEPTIONS = new Set([
  "clawsweeper:human-review",
  "clawsweeper:manual-only",
  "clawsweeper:bulk-filed",
]);

type ReviewSourceRevisionLabelOptions = {
  preserveAutomationModeLabels?: boolean;
};

export function isIgnorableReviewSourceRevisionLabel(
  value: unknown,
  options: ReviewSourceRevisionLabelOptions = {},
): boolean {
  const label = String(value ?? "")
    .trim()
    .toLowerCase();
  if (!label || label === "proof: override") return !label;
  if (
    options.preserveAutomationModeLabels &&
    (label === AUTOMERGE_LABEL || label === AUTOFIX_LABEL)
  ) {
    return false;
  }
  return (
    /^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label) ||
    /^p[0-3]$/.test(label) ||
    label === "maturity:stable" ||
    label === "feature: ✨ showcase" ||
    label === "good first issue" ||
    label === "mantis: telegram-visible-proof" ||
    label === "proof: telegram-e2e" ||
    label === "triage: needs-real-behavior-proof" ||
    (label.startsWith("clawsweeper:") && !REVIEW_SOURCE_LABEL_EXCEPTIONS.has(label)) ||
    label === "clawsweeper-recovery-stuck" ||
    label === "no-stale" ||
    label === "stale"
  );
}

export function reviewSourceRevisionLabels(
  value: unknown,
  options: ReviewSourceRevisionLabelOptions = {},
): string[] {
  if (!Array.isArray(value)) return [];
  return [
    ...new Set(
      value
        .map((entry) => {
          const record = entry !== null && typeof entry === "object" ? entry : {};
          return String((record as { name?: unknown }).name ?? entry)
            .trim()
            .toLowerCase();
        })
        .filter((label) => !isIgnorableReviewSourceRevisionLabel(label, options)),
    ),
  ].sort();
}
